export function getMatchesForTeam(slug: string): TeamMatch[] {
  return teamMatches[slug] ?? []
}

export function getUpcomingMatches(slug: string, todayIso?: string): TeamMatch[] {
  const today =
    todayIso ??
    new Intl.DateTimeFormat('en-CA', {
      timeZone: 'Europe/Brussels',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).format(new Date())
  return getMatchesForTeam(slug)
    .filter((m) => m.dateIso >= today)
    .sort((a, b) => a.dateIso.localeCompare(b.dateIso) || a.time.localeCompare(b.time))
}

export function getNextMatch(slug: string): TeamMatch | undefined {
  return getUpcomingMatches(slug)[0]
}

